<script setup lang="ts">import {computed,onMounted,ref,watch} from 'vue'; import {useRoute} from 'vue-router'; import {ElMessage} from 'element-plus'; import {api} from '../api'; const route=useRoute(); const rows=ref<any[]>([]); const loading=ref(false); const dialog=ref(false); const payload=ref('{}'); const resource=computed(()=>String(route.params.resource)); const labels:Record<string,string>={standards:'食材标准库',suppliers:'供应商',plans:'采购计划',inquiries:'询价/竞价',orders:'采购订单',deliveries:'配送',inspections:'智能验收',inventory:'库存批次',settlements:'结算'}; async function load(){loading.value=true;try{rows.value=(await api.get('/'+resource.value)).data}finally{loading.value=false}} async function create(){try{await api.post('/'+resource.value,JSON.parse(payload.value));dialog.value=false;await load();ElMessage.success('已保存')}catch(e){ElMessage.error('保存失败：请检查必填字段、JSON 格式和角色权限')}} onMounted(load);watch(resource,load);</script><template><div class="bar"><h1>{{labels[resource]||resource}}</h1><div><el-button type="primary" @click="dialog=true">新增</el-button><el-button @click="load">刷新</el-button></div></div><el-table :data="rows" v-loading="loading" stripe><el-table-column v-for="key in (rows[0]?Object.keys(rows[0]):['id'])" :key="key" :prop="key" :label="key" min-width="150"/></el-table><el-dialog v-model="dialog" :title="'新增'+(labels[resource]||resource)" width="600"><p>输入符合接口字段的 JSON 数据。</p><el-input v-model="payload" type="textarea" :rows="12"/><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></template></el-dialog></template><style scoped>.bar{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}</style>
